package com.osrscolorlock.colorlock;

import com.google.gson.Gson;

import java.nio.file.Files;
import java.nio.file.Path;

import org.junit.Assert;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;
import org.junit.Rule;

public class ManifestDiskCacheTest
{
	@Rule
	public TemporaryFolder temp = new TemporaryFolder();

	@Test
	public void roundTripSnapshot() throws Exception
	{
		Path file = temp.newFile("items-manifest.json").toPath();
		Gson gson = new Gson();
		ManifestDiskCache cache = new ManifestDiskCache(gson, file);

		ManifestItem row = gson.fromJson(
			"{\"id\":284,\"name\":\"Plague jacket\",\"usableColors\":[\"yellow\"],"
				+ "\"questColorLockKeys\":[\"sheep_herder\"]}",
			ManifestItem.class);

		cache.save("https://example.test/api/v1/items", 91, java.util.List.of(row));

		ManifestDiskCache.Snapshot snap = cache.load();
		Assert.assertNotNull(snap);
		Assert.assertEquals(91, snap.schemaVersion);
		Assert.assertEquals(1, snap.items.size());
		Assert.assertEquals(284, snap.items.get(0).getId());
		Assert.assertTrue(Files.isRegularFile(file));
	}
}

package com.osrscolorlock.colorlock;

import net.runelite.client.util.Text;

final class ColorLockMenuRules
{
	private ColorLockMenuRules()
	{
	}

	static boolean isRestrictedUseVerb(String rawOption)
	{
		if (rawOption == null)
		{
			return false;
		}
		String opt = Text.removeTags(rawOption).trim().toLowerCase();
		switch (opt)
		{
			case "eat":
			case "drink":
			case "equip":
			case "wield":
			case "wear":
			case "release":
				return true;
			default:
				return false;
		}
	}
}

package com.osrscolorlock.colorlock;

import java.util.concurrent.ConcurrentLinkedQueue;

/** FIFO labels from collection-log chat lines, paired one-per-drop when varps increase. */
final class ColorLockCollectionLogItemQueue
{
	private final ConcurrentLinkedQueue<String> pendingItems = new ConcurrentLinkedQueue<>();

	void offerFromChat(String raw)
	{
		if (raw == null)
		{
			return;
		}
		String item = raw.trim();
		if (!item.isEmpty())
		{
			pendingItems.offer(item);
		}
	}

	String pollForDrop()
	{
		return pendingItems.poll();
	}

	void clear()
	{
		pendingItems.clear();
	}

	int size()
	{
		return pendingItems.size();
	}
}

